#!/usr/bin/env python3
"""從權威 Markdown／Schema 產生無外部依賴的深色 HTML。"""
from pathlib import Path
import json,re,html
from markdown_it import MarkdownIt
from bs4 import BeautifulSoup
ROOT=Path(__file__).resolve().parents[1]
escape=html.escape
MD=MarkdownIt('commonmark',{'html':True}).enable('table')
def doc_id(path):return 'doc-'+re.sub('[^a-z0-9]+','-',str(path).lower()).strip('-')

def render(path):
    content=MD.render((ROOT/path).read_text())
    soup=BeautifulSoup(content,'html.parser')
    for tag in soup.select('a[href]'):
        href=tag['href']
        if href.startswith(('https://','http://')):
            tag['target']='_blank';tag['rel']='noopener noreferrer'
        elif not href.startswith('#'):
            name,_,frag=href.partition('#')
            full=(ROOT/path).parent/name
            rel=full.resolve().relative_to(ROOT.resolve())
            tag['href']='#'+(frag or doc_id(rel))
    for table in soup.select('table'):
        table.wrap(soup.new_tag('div',attrs={'class':'table-scroll'}))
    return str(soup)

