 # Legacy SVG styles use generic selectors: scope every embedded style to its figure.
 soup=BeautifulSoup(htmltext,'html.parser')
 for i in range(1,5):
  fig=soup.find(id=f'V{i}')
  for style in fig.select('svg style'):
   text=style.string or ''
   text=re.sub(r'([^{}]+)\{',lambda m:','.join(f'#V{i} '+sel.strip() for sel in m[1].split(','))+'{',text)
   style.string=text
 (ROOT/'index.html').write_text(str(soup))
 return ROOT/'index.html'
